import {HeroPlane} from './hero-plane.js';
export function bindHangar(hero,session,t,getReduced,onSelect){
 let identity=null,preview=null,choice='classic',saving=false;
 const dialog=document.createElement('dialog');dialog.className='hangar-dialog';dialog.setAttribute('aria-label',t('Your hangar','我的机库'));document.body.append(dialog);
 const designs=[['classic','Classic','经典飞机'],['sapphire','Sapphire','蓝宝石'],['gold','Golden captain','金翼机长'],['night','Midnight','星夜巡航']];
 function showModel(){preview?.dispose();const host=dialog.querySelector('.hangar-stage');preview=new HeroPlane(host,{model:choice!=='classic',style:choice,reduced:getReduced()});preview.wrap.setAttribute('aria-label',t('Enlarged airplane preview','放大的飞机预览'));preview.wrap.removeAttribute('role');dialog.querySelectorAll('[data-plane]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.plane===choice)));dialog.querySelector('.hangar-hint').textContent=choice==='classic'?t('Classic illustrated airplane','经典插画飞机'):t('Drag the 3D plane to rotate it','拖动3D飞机可旋转查看');const button=dialog.querySelector('[data-plane-save]');button.disabled=!identity?.appearance?.member||saving;button.textContent=identity?.appearance?.member?t('Use this plane','使用这架飞机'):t('Membership required to select','会员可选择专属飞机');}
 function open(){choice=identity?.appearance?.plane||'classic';dialog.innerHTML=`<button type="button" class="close" data-hangar-close aria-label="${t('Close','关闭')}">×</button><span class="sample-pill">${t('YOUR HANGAR','我的机库')}</span><h2>${t('Ready for your next flight','选一架，准备起飞')}</h2><div class="hangar-stage"></div><p class="hangar-hint">${t('Drag the 3D plane to rotate it','拖动3D飞机可旋转查看')}</p><div class="hangar-choices">${designs.map(([id,en,zh])=>`<button type="button" class="secondary" data-plane="${id}">${t(en,zh)}</button>`).join('')}</div><p class="hangar-notice" role="status">${t('Member planes appear on your homepage. Game pieces keep their seat colors.','会员飞机显示在你的主页；对局棋子保留席位颜色。')}</p><button type="button" class="primary" data-plane-save></button>`;dialog.showModal();showModel();}
 function bindHero(){hero.wrap.setAttribute('role','button');hero.wrap.setAttribute('tabindex','0');hero.wrap.setAttribute('aria-label',t('Open airplane hangar','查看飞机机库'));hero.wrap.onclick=open;hero.wrap.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();open();}};}
 bindHero();
 const onIdentity=event=>{identity=event.detail;const style=identity?.appearance?.plane||'classic';if(hero.wrap.dataset.planeStyle!==style){hero=onSelect(style);hero.wrap.dataset.planeStyle=style;bindHero();}};session.addEventListener('identity',onIdentity);session.addEventListener('profile-updated',onIdentity);
 dialog.addEventListener('click',async e=>{if(e.target.closest('[data-hangar-close]')){dialog.close();return;}const option=e.target.closest('[data-plane]');if(option&&!saving){choice=option.dataset.plane;showModel();return;}if(!e.target.closest('[data-plane-save]')||saving||!identity?.appearance?.member)return;saving=true;showModel();try{await session.request('/api/account/appearance',{plane:choice});identity=await session.request('/api/me');session.dispatchEvent(new CustomEvent('identity',{detail:identity}));dialog.querySelector('.hangar-notice').textContent=t('Saved. Your homepage plane is updated.','已保存，主页飞机已更新。');}catch{dialog.querySelector('.hangar-notice').textContent=t('Save failed. Please retry.','保存失败，请重试。');}finally{saving=false;showModel();}});
 dialog.addEventListener('close',()=>{preview?.dispose();preview=null;});
 let drag=null;dialog.addEventListener('pointerdown',e=>{if(e.target.closest('.hangar-stage')&&preview?.model){drag={x:e.clientX,y:preview.model.rotation.y};e.target.setPointerCapture(e.pointerId);}});dialog.addEventListener('pointermove',e=>{if(drag&&preview?.model){preview.model.rotation.y=drag.y+(e.clientX-drag.x)*.012;preview.render(performance.now());}});dialog.addEventListener('pointerup',()=>drag=null);dialog.addEventListener('pointercancel',()=>drag=null);
}
